shell_commands:
/bin/zsh -lc "cat >> specs/hal-engine-tool-input-validation/spec.md <<'EOF'

- The registry loads its JSON Schema validator in the Node and Jest module environments and reports nested required property paths ([validated by: loads the validator and reports nested required paths](../../src/orchestration/tools/registry.module.test.ts#L4)).
EOF
cat > src/orchestration/tools/registry.module.test.ts <<'EOF'
import {ToolRegistry} from './registry.js';

// specs/hal-engine-tool-input-validation/spec.md#11
it('loads the validator and reports nested required paths', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'nested', description: 'Nested input', inputSchema: {type: 'object', properties: {address: {type: 'object', required: ['city']}}}},
    async () => 'accepted'
  );
  const response = await registry.execute('nested', {address: {}});
  expect(response.result).toMatch(/address\\/city.*required|required.*address\\/city/i);
});
EOF
timeout 300 npm test -- --runTestsByPath src/orchestration/tools/registry.module.test.ts --runInBand --coverage=false"
